// SW1 - Intake Telemetry Tap — v1.0
// Type: Code (Run Once for Each Item)
// Purpose: Capture what SW1 receives from 2A

const j = $json || {};
const tap = {
  ts: new Date().toISOString(),
  workflow: 'SW1',
  node: 'intake',
  orderId: j.amazonOrderId || j.orderId,
  characterHash: j.characterHash,
  correlationId: j.correlationId,
  __isRetry: !!j.__isRetry,
  pose: {
    workingPoseNumber: j.workingPoseNumber,
    poseNumber: j.poseNumber,
    currentPoseNumber: j.currentPoseNumber,
    poseNN: j.poseNN
  },
  envelope_check: {
    has_baseCharacterKey: !!j.baseCharacterKey,
    has_poseRefKey: !!j.poseRefKey,
    has_hairRefS3Key: !!j.hairRefS3Key,
    has_hairPromptMeta: !!j.hairPromptMeta,
    has_posePromptPreface: !!j.posePromptPreface,
    preface_length: (j.posePromptPreface || '').length
  },
  retryAttempt: j.retryAttempt || 0,
  retryTag: j.retryTag,
  severity: 'INFO',
  msg: '__isRetry=' + (!!j.__isRetry) + ', pose=' + (j.poseNumber || '?')
};

// Optional: POST to diagnostic sink or just console.log
console.log('SW1_INTAKE:', JSON.stringify(tap));

return { json: j, binary: $binary };

// Extract Generated Image (Gemini) — v2j  ✅ strict-but-robust characterHash; stable baseCharacterKey
// Works with either HTTP JSON (inlineData) or HTTP Download (binary).
// Guarantees: binary.generated present; keeps pose/character via rehydrate; returns SINGLE object.
//
// CHANGES vs v2h:
// - Add ctx.ctx.characterHash and characterPath parsing.
// - Expand ctxCandidates to include Schema/Init nodes (e.g., "Schema Check + Defaults").
// - Robust hash resolution: supports '/characters/<hex>/' and 'characters_<hex>_' patterns (e.g., generatedAttemptKey).
// - Additional known-key scans (baseCharacterKey, baseRefPublicUrl, basePublicUrl, __meta.storageKey, __meta.baseUploadKey, __meta.generatedAttemptKey).
// - Improved diagnostics when missing.

const res   = $json || {};
const bIn   = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = ($input?.item?.pairedItem?.item ?? (typeof $itemIndex === 'number' ? $itemIndex : 0));

/* --------------------------- helpers --------------------------- */
function clampPose(n){ return Math.max(0, Math.min(999, Number(n || 0))); }
function zpad(n,w=2){ const s=String(Math.max(0, Number(n)|0)); return s.length>=w?s:'0'.repeat(w-s.length)+s; }

function stripInlineDataDeep(o){
  if (!o || typeof o !== 'object') return o;
  if (Array.isArray(o)) return o.map(stripInlineDataDeep);
  const x = {};
  for (const [k,v] of Object.entries(o)) {
    if (k === 'inlineData' && v && typeof v === 'object') {
      const mimeType = v.mimeType || undefined;
      x.inlineData = mimeType ? { mimeType } : {};
    } else {
      x[k] = stripInlineDataDeep(v);
    }
  }
  return x;
}

// make a *slim* copy of context so we never re-attach base64
function slimCtx(j){
  if (!j || typeof j !== 'object') return {};
  const c = { ...j };
  delete c.requestBody;
  delete c.contents;
  delete c.systemInstruction;
  delete c.qaRequestBody;
  return stripInlineDataDeep(c);
}

function normalizeBinary(b, fallbackName){
  if (!b) return null;
  return {
    ...b,
    mimeType: b.mimeType || 'image/png',
    fileName: b.fileName || b.fileNameOriginal || fallbackName
  };
}
function preferredIndex(arr){ return (itemIx>=0 && itemIx<arr.length) ? itemIx : 0; }
function safeItems(nodeName, rIx){ try { return $items(nodeName, 0, rIx) || []; } catch { return []; } }
function getItemFromNode(nodeName, rIx){
  const arr=safeItems(nodeName, rIx);
  if (!arr.length) return null;
  const ix=preferredIndex(arr);
  return arr[ix] || arr[0] || null;
}

function looksLikePoseName(name){
  const n = String(name||'').toLowerCase();
  if (/pose[_\-]?\d{1,3}\.(png|jpe?g|webp)$/.test(n)) return true;
  if (/^p[\-_]?\d{1,3}\.(png|jpe?g|webp)$/.test(n))   return true;
  return /(^|\/)pose(\.|_|-|$)/.test(n);
}
function pickPoseFromMap(map, fallback){
  if (!map) return null;
  if (map.pose && looksLikePoseName(map.pose.fileName || map.pose.fileNameOriginal || 'pose.png')) return normalizeBinary(map.pose, fallback);
  for (const k of Object.keys(map)){ const b=map[k]; const name=b?.fileName || b?.fileNameOriginal; if (looksLikePoseName(name)) return normalizeBinary(b, fallback); }
  if (map.pose) return normalizeBinary(map.pose, fallback);
  return null;
}
function pickCharacterFromMap(map, fallback){
  if (!map) return null;
  if (map.character) return normalizeBinary(map.character, fallback);
  if (map.base) return normalizeBinary(map.base, fallback);
  for (const k of Object.keys(map)){ const b=map[k]; const n=String(b?.fileName || b?.fileNameOriginal || '').toLowerCase(); if (/character|base/.test(n)) return normalizeBinary(b, fallback); }
  return null;
}

// Pick generated image from an HTTP node's binary map
function pickGeneratedFromMap(map, fallback){
  if (!map) return null;
  const keysPriority = ['generated','output','image','file','data','result','content'];
  for (const k of keysPriority) {
    const b = map[k];
    if (b && /^image\//i.test(String(b.mimeType||''))) return normalizeBinary(b, fallback);
  }
  for (const [, b] of Object.entries(map)) {
    if (b && /^image\//i.test(String(b.mimeType||''))) return normalizeBinary(b, fallback);
  }
  return null;
}

function rehydrateFrom(nodeNames, picker, fallback){
  const runs=[runIx,0];
  for (const r of runs){
    for (const name of nodeNames){
      const it=getItemFromNode(name,r);
      if (!it?.binary) continue;
      const picked=picker(it.binary, fallback);
      if (picked) return { bin:picked, from:`${name}#run${r}`, json:(it.json||{}) };
    }
  }
  return null;
}

function findInline(obj, path = []) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.inlineData?.data) return { data: String(obj.inlineData.data), mime: obj.inlineData.mimeType || 'image/png', path: path.concat('inlineData') };
  if (Array.isArray(obj)) { for (let i=0;i<obj.length;i++){ const h=findInline(obj[i], path.concat(i)); if (h) return h; } return null; }
  if (obj.candidates) return findInline(obj.candidates, path.concat('candidates'));
  if (obj.content)    return findInline(obj.content,    path.concat('content'));
  if (obj.parts)      return findInline(obj.parts,      path.concat('parts'));
  if (obj[0])         return findInline(obj[0],         path.concat(0));
  for (const [k,v] of Object.entries(obj)) { if (k==='inlineData') continue; const h=findInline(v, path.concat(k)); if (h) return h; }
  return null;
}
function sha1(buf){ return require('crypto').createHash('sha1').update(buf).digest('hex'); }

/* ---------- characterHash resolution (strict but covers your patterns) ---------- */
const PATH_RE_SLASH = /(?:^|[\/\\])characters[\/\\]([a-f0-9]{8,64})(?:[\/\\]|$)/i;     // …/characters/<hex>/…
const PATH_RE_UNDER = /(?:^|[_\-])characters[_\-]([a-f0-9]{8,64})(?:[_\-]|$)/i;        // characters_<hex>_…

function extractHashFromString(s){
  if (!s) return null;
  const t = String(s);
  let m = t.match(PATH_RE_SLASH);
  if (m) return m[1];
  m = t.match(PATH_RE_UNDER);
  if (m) return m[1];
  return null;
}
function extractHashFromBinary(bin){
  if (!bin) return null;
  return extractHashFromString(bin.filePath || bin.path || bin.fileName || bin.fileNameOriginal || '');
}
function scanForHashStrings(obj){
  const out = [];
  (function walk(x){
    if (!x) return;
    if (typeof x === 'string') out.push(x);
    else if (Array.isArray(x)) x.forEach(walk);
    else if (typeof x === 'object') for (const v of Object.values(x)) walk(v);
  })(obj);
  return out;
}

// Resolve characterHash with a source tag.
function resolveCharacterHash(res, ctxJson, characterBin){
  // 1) explicit fields first
  const chain = [
    ['res.characterHash',               res?.characterHash],
    ['res.characterSpecs.hash',         res?.characterSpecs?.hash],
    ['ctx.characterHash',               ctxJson?.characterHash],
    ['ctx.ctx.characterHash',           ctxJson?.ctx?.characterHash],       // ← nested ctx
    ['ctx.characterSpecs.hash',         ctxJson?.characterSpecs?.hash],
    ['ctx.__meta.characterHash',        ctxJson?.__meta?.characterHash],
    ['res.__meta.characterHash',        res?.__meta?.characterHash],
  ];
  for (const [src,val] of chain){
    if (val !== undefined && val !== null && val !== '') return { hash:String(val), source:src };
  }

  // 2) well-known key strings that include the path or filename
  const knownStrings = [
    ctxJson?.characterPath,                 // "characters/<hash>"
    ctxJson?.baseCharacterKey,
    res?.baseCharacterKey,
    ctxJson?.baseRefPublicUrl,
    res?.baseRefPublicUrl,
    ctxJson?.basePublicUrl,
    res?.basePublicUrl,
    ctxJson?.__meta?.storageKey,
    ctxJson?.__meta?.baseUploadKey,
    res?.__meta?.storageKey,
    res?.__meta?.baseUploadKey,
    ctxJson?.__meta?.generatedAttemptKey,   // e.g., "characters_<hash>_base.png"
    res?.__meta?.generatedAttemptKey,
  ].filter(Boolean);

  for (const s of knownStrings){
    const hit = extractHashFromString(s);
    if (hit) return { hash: hit, source: 'known-key' };
  }

  // 3) from character binary path or name
  const fromBin = extractHashFromBinary(characterBin);
  if (fromBin) return { hash: fromBin, source: 'binary.character.path' };

  // 4) strict scan across all strings in ctx/res (covers pose/base URLs, etc.)
  const strings = scanForHashStrings(ctxJson).concat(scanForHashStrings(res));
  for (const s of strings){
    const hit = extractHashFromString(s);
    if (hit) return { hash: hit, source: 'strict-scan' };
  }

  return { hash: null, source: 'missing' };
}

function prefer(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } return null; }

/* ------------------------ thresholds ------------------------ */
const isMock = /mock/i.test(res.modelVersion || res?.candidates?.[0]?.modelVersion || '')
            || res.__testMode === true
            || res.__allowTinyImage === true;
const minInlineBytes = Number.isFinite(Number(res.minInlineBytes)) ? Number(res.minInlineBytes) : (isMock ? 1 : 100);

/* ------------------------ 1) obtain GENERATED ------------------------ */
let genBuf = null, genBinary = null, genSource = null, mime = 'image/png';

if (bIn.generated) { genBinary = normalizeBinary(bIn.generated, 'generated.png'); genSource = 'binary.generated'; }
if (!genBinary && bIn.generated_inline) { genBinary = normalizeBinary(bIn.generated_inline, 'generated.png'); genSource = 'binary.generated_inline'; }

// Try to pull file binary from HTTP nodes
const HTTP_NODE_CANDIDATES = [
  'Generate Character in Pose','HTTP: Generate Character in Pose','HTTP: Pose Generation','Gemini Pose Generation','HTTP'
];
if (!genBinary) {
  const re = rehydrateFrom(HTTP_NODE_CANDIDATES, pickGeneratedFromMap, 'generated.png');
  if (re) { genBinary = re.bin; genSource = re.from; }
}

// Fallback: inlineData in JSON
let inlinePath = null;
if (!genBinary && !genBuf) {
  let hit = findInline(res);
  if (!hit && isMock) hit = { data: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==", mime: "image/png", path: ["__mock_fallback"] };
  if (hit) {
    const b64 = String(hit.data || '');
    if (!b64 || b64.length < minInlineBytes) {
      throw new Error(`Extract Generated Image: inline image too short (${b64.length} < ${minInlineBytes})`);
    }
    genBuf = Buffer.from(b64, 'base64');
    mime   = hit.mime || 'image/png';
    genSource = 'json.inlineData';
    inlinePath = hit.path;
  }
}

// If still nothing, explode with clear diagnostics
if (!genBinary && !genBuf) {
  const presentKeys = Object.keys(bIn || {});
  const finish = res?.candidates?.[0]?.finishReason || res.finishReason || 'UNKNOWN';
  throw new Error(`Extract Generated Image: no inlineData image found (finishReason=${finish}); present binary keys: [${presentKeys.join(', ')}]`);
}

/* ---------------- 2) context ---------------- */
const ctxCandidates = [
  // Strongly-typed context sources common in your flow
  'Schema Check + Defaults','Schema Check + Defaults — Retry','Schema + Defaults','Schema Check',
  'Init / Validate Inputs','Init — Validate Inputs','Init/Validate Inputs','Init',
  // Existing payload droppers / prep
  'Drop Pose Payload','Drop Pose Payload1','Drop Pose Payload — Retry',
  'Drop QA Payload','Drop QA Payload — Retry',
  'Prepare Gemini (POSE)','Prepare Gemini (POSE) — Retry'
];
let ctx = null, ctxSourceNode = null;
for (const name of ctxCandidates){
  const hitItem = getItemFromNode(name, runIx) || getItemFromNode(name, 0);
  if (hitItem) { ctx = hitItem; ctxSourceNode = name; break; }
}
const rawCtxJson = ctx?.json || {};
const ctxJson = slimCtx(rawCtxJson);
const ctxBin  = ctx?.binary || {};
const ctxWasSanitized = /drop.*payload/i.test(String(ctxSourceNode||'').toLowerCase());

/* ---------------- 3) pose number + labels ---------------- */
let poseNum =
  res.poseNumber ?? res.currentPoseNumber ?? res.__meta?.poseNumber ??
  ctxJson.poseNumber ?? ctxJson.currentPoseNumber ?? ctxJson.__meta?.poseNumber ?? null;
poseNum = Number.isFinite(Number(poseNum)) ? clampPose(poseNum) : null;
const NN = (poseNum !== null && poseNum !== undefined) ? zpad(poseNum,2) : 'xx';

// Keep both label styles available downstream
const poseLabel    = prefer(res.poseNN, ctxJson.poseNN, ((poseNum !== null && poseNum !== undefined) ? `pose${NN}` : null));
const poseLabelHy  = prefer(res.poseNN_hyphen, ctxJson.poseNN_hyphen, ((poseNum !== null && poseNum !== undefined) ? `pose-${NN}` : null));

/* ---------------- 4) ensure POSE ---------------- */
let poseBin = bIn.pose ? normalizeBinary(bIn.pose, 'pose.png') : null;
let poseSource = poseBin ? 'current' : null;

if (!poseBin && ctxBin && Object.keys(ctxBin).length){
  const pick = pickPoseFromMap(ctxBin, 'pose.png');
  if (pick) { poseBin = normalizeBinary(pick, 'pose.png'); poseSource = ctxWasSanitized ? 'sanitized ctx' : 'prepare ctx'; }
}
if (!poseBin) {
  const re = rehydrateFrom(
    ['Reattach Binaries (For QA)','Reattach Binaries (For Retry Gen)','Download Pose Reference','Download Pose Ref (IMAGE P)','Download a file (pose)','Carry Pose Index','Prepare Pose Reference','Prepare Upload','Prepare Gemini (POSE)'],
    pickPoseFromMap,
    'pose.png'
  );
  if (re) { poseBin = re.bin; poseSource = re.from; }
}

/* ---------------- 5) ensure CHARACTER ---------------- */
let characterBin = bIn.character ? normalizeBinary(bIn.character, 'character.png') : null;
let characterSource = characterBin ? 'current' : null;

if (!characterBin && bIn.base) { characterBin = normalizeBinary(bIn.base, 'character.png'); characterSource = 'current (base)'; }
if (!characterBin && ctxBin && Object.keys(ctxBin).length){
  const pick = pickCharacterFromMap(ctxBin, 'character.png');
  if (pick) { characterBin = pick; characterSource = ctxWasSanitized ? 'sanitized ctx' : 'prepare ctx'; }
}
if (!characterBin) {
  const re = rehydrateFrom(
    ['Download base character','Download Base Character (R2)','Resolve Base Character Key','Prepare Binary (Base)','Reattach Binaries (For QA)','Prepare Upload','Prepare Gemini (POSE)'],
    pickCharacterFromMap,
    'character.png'
  );
  if (re) { characterBin = re.bin; characterSource = re.from; }
}

/* ------------------------ 6) resolve hash (+source) ------------------------ */
const { hash: resolvedHash, source: hashSource } = resolveCharacterHash(res, ctxJson, characterBin);
let characterHash = resolvedHash;
const safeHash = characterHash || 'nohash';

/* ---------------- 7) filename for GENERATED ---------------- */
const baseName = res.correlationId
  ? String(res.correlationId).replace(/[^\w\-]+/g, '_')
  : `characters_${safeHash}_pose${NN}`;
const fileName = `${baseName}.png`;

/* ---------------- 8) construct output binary ---------------- */
const outBinary = {};
// carry through pose/character/hair/skin (including 'base' variant)
for (const k of ['pose','character','base','hair','skin']) if (bIn[k]) outBinary[k] = bIn[k];

if (genBinary) {
  // promote upstream binary; normalize name
  outBinary.generated = { ...genBinary, fileName };
  mime = genBinary.mimeType || mime;
} else {
  // we decoded from inlineData
  const genBin = await this.helpers.prepareBinaryData(genBuf, fileName, mime);
  genBin.mimeType = mime;
  genBin.fileExtension = 'png';
  outBinary.generated = genBin;
}

/* ---------------- 9) SLIM JSON + breadcrumbs ---------------- */
const resSlim = stripInlineDataDeep(res);

// (Optional) rebuild baseCharacterKey if we have assetsRoot + characterHash
const assetsRoot   = prefer(ctxJson.assetsRoot, res.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
let baseCharacterKey = prefer(res.baseCharacterKey, ctxJson.baseCharacterKey, null);
if (!baseCharacterKey && characterHash) {
  baseCharacterKey = `${assetsRoot.replace(/\/+$/,'')}/characters/${characterHash}/base-character.png`;
}

const outJson = {
  ...slimCtx(ctxJson),
  ...resSlim,

  // lock the stable hash and key
  characterHash: characterHash ?? ctxJson.characterHash ?? ctxJson?.ctx?.characterHash ?? res.characterHash ?? null,
  baseCharacterKey: baseCharacterKey || undefined,

  poseNumber: poseNum,
  currentPoseNumber: poseNum,
  poseNN: poseLabel,             // e.g., "pose01"
  poseNN_hyphen: poseLabelHy,    // e.g., "pose-01"
  generatedFileName: fileName,
  generatedImage: { mimeType: mime, size: (genBinary ? undefined : (genBuf?.length || undefined)) },
  __meta: {
    ...(res.__meta || {}),
    extractGenerated: {
      source: genSource,
      inlinePath,
      isMock,
      minInlineBytes,
      finishReason: res?.candidates?.[0]?.finishReason || res.finishReason || null,
      usage: res.usageMetadata || null,
      poseAttached: !!poseBin,
      poseSource,
      characterAttached: !!characterBin,
      characterSource,
      presentBinaryKeysIn: Object.keys(bIn || {}),
      presentBinaryKeysOut: Object.keys(outBinary || {}),
      ctxFrom: ctxSourceNode || null,
      filenameBase: baseName,
      poseNumber: poseNum,
      sha1_generated: genBinary ? null : (genBuf ? sha1(genBuf) : null),
      hashSource,
      checkedSources: {
        hasCtx: !!ctxJson && Object.keys(ctxJson).length>0,
        hasCharacterPath: !!ctxJson?.characterPath,
        hasBaseCharacterKey: !!(ctxJson?.baseCharacterKey || res?.baseCharacterKey),
        hasGeneratedAttemptKey: !!(ctxJson?.__meta?.generatedAttemptKey || res?.__meta?.generatedAttemptKey),
      }
    }
  }
};

console.log({
  node: 'Extract Generated Image v2j',
  poseNum,
  poseNN: outJson.poseNN,
  poseNN_hyphen: outJson.poseNN_hyphen,
  genSource,
  genSize: genBinary ? genBinary.fileSize : (genBuf?.length || 0),
  characterHash: characterHash || '(none)',
  hashSource,
  baseCharacterKey,
  binaryKeysOut: Object.keys(outBinary)
});

/* ---------------- 10) return SINGLE object ---------------- */
return {
  json: outJson,
  binary: outBinary,
  pairedItem: $input?.item?.pairedItem ?? { item: itemIx },
};

// Build Dynamic Pose Prompt — EACH — v5.3 BASE-HAIR COLOR LOCK + ANTI-LEAK
// Uses short semantic labels (BASE, POSE) for clarity with vision models
// Hair color MUST EXACTLY match BASE (ignore any color in HAIR CHIP)
// Emits: posePromptBlock + userPromptText + poseNN + poseNN_hyphen

const j = $json || {};
const b = $binary || {};
const cs = j.characterSpecs || {};

/* ========== LABEL CONSTANTS ========== */
// Label tokens used in text so Gemini always knows which image is which
const LABEL_BASE = 'BASE';                  // appearance lock (base character reference)
const LABEL_POSE = 'POSE';                  // pose lock (mannequin/reference pose)
const LABEL_HAIR = 'HAIR CHIP';             // optional hair override, silhouette-only

/* ========== HELPERS & FLAGS ========== */
function asBool(v){
  if (v === true) return true;
  if (v === false || v == null) return false;
  if (typeof v === 'number') return v === 1;
  if (typeof v === 'string') return /^(true|1|yes|y)$/i.test(v.trim());
  return false;
}
function isBadHash(h){ return !h || h === 'nohash' || h === 'unknown' || typeof h !== 'string' || h.length < 4; }
function norm(s){ return String(s||'').toLowerCase().trim(); }
function clampPose(n){ return Math.max(0, Math.min(12, Number(n||0))); }
function asInt(v){ const n=Number(v); return Number.isFinite(n)?Math.floor(n):null; }
function bool(v){ if (typeof v==='boolean') return v; if (typeof v==='number') return v!==0; if (typeof v==='string') return /^(true|yes|y|1)$/i.test(v.trim()); return false; }
function pad2(n){ return String(n).padStart(2,'0'); }

const FLAGS = {
  __testMode: [
    j.__testMode, j.testMode,
    j.__meta?.__testMode, j.ctx?.__testMode, j.ctx?.testMode
  ].some(asBool)
};
FLAGS.testMode = FLAGS.__testMode;

/* ========== SKIN TONE (CHEEK BLUSH CONTROL) ========== */
const skinToneRaw =
  j.skinTone ??
  j.childSkinTone ??
  cs.skinTone ??
  cs.childSkinTone ??
  cs.baseSkinTone ??
  null;

const skinToneKey = norm(skinToneRaw || '');
const isBrownDeep = /brown\s*-?\s*deep/.test(skinToneKey);
const allowCheekBlush = !isBrownDeep;

/* ========== UPSTREAM HAIR META LOOKUP ========== */
const runIx  = (typeof $runIndex  === 'number') ? $runIndex  : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;
function safeItems(name, rIx) { try { return $items(name, 0, rIx) || []; } catch { return []; } }
const HAIR_NODE_NAMES = [
  'Build Dynamic Hairstyle Description',
  'Build Dynamic Hairstyle Description — EACH mode',
  'Build Dynamic Hairstyle Description — v1.5',
];
function fetchHairMeta() {
  for (const n of HAIR_NODE_NAMES) {
    const now  = safeItems(n, runIx);
    const seed = safeItems(n, 0);
    const pick = (arr) => (arr[itemIx]?.json) || (arr[0]?.json) || null;
    const cand = pick(now) || pick(seed);
    if (!cand) continue;
    const m = cand.hairPromptMeta || {};
    return {
      styleKey:      m.styleKey || cand.hairStyleCanonical || null,
      colorHex:      m.colorHex || cand.hairColorHex || m.color || null, // not used for color; BASE color is authoritative
      clothingCanon: m.clothingTypeCanonical || cand.clothingTypeCanonical || null,
      sourceNode:    n
    };
  }
  return { styleKey: null, colorHex: null, clothingCanon: null, sourceNode: null };
}
const upstreamHair = fetchHairMeta();

/* ========== FALLBACKS ========== */
const hairPromptMetaLocal = j.hairPromptMeta || {};
const styleKeyFallback = upstreamHair.styleKey || hairPromptMetaLocal.styleKey || j.hairStyleCanonical || 'side-part';
// IMPORTANT: hair color must come from BASE; do not inject chip hex
const colorHexFallback = null;
const clothingTypeCanonical = upstreamHair.clothingCanon || hairPromptMetaLocal.clothingTypeCanonical || j.clothingTypeCanonical || 'tshirt-shorts';

/* ========== POSE NUMBER & NORMALIZED KEYS ========== */
const poseNum = clampPose(j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber ?? 1);
const poseNN = j.poseNN || `pose${pad2(poseNum)}`;
const poseNN_hyphen = j.poseNN_hyphen || `pose-${pad2(poseNum)}`;

/* ========== POSE MAPS ========== */
const POSE_PROMPT_MAP = {
  '0': `BOTH hands over heart. Feet under hips, flat. Torso upright; shoulders down. Both hands lightly on heart center; fingers relaxed. Eyes softly closed; small closed-mouth smile. Body facing striaght-forward; clean silhouette.`,
  '1': `Walking step. Front foot forward and flat; rear heel slightly lifted. Torso upright, shoulders level. Natural counter-swing of arms (opposite arm forward to leading leg, other arm visible at side of the body, not behind the body). Body and head facing forward; gaze ahead; gentle smile.`,
  '2': `Walking while looking up higher. Front foot forward; rear heel lifted. Elbows softly bent; hands near torso (light fists). Chin raised; head tilted up/right; eyes looking 45 degrees up from horizon. Torso upright; shoulders level.`,
