    '- ABSOLUTELY NO flyaways, loose strands, wisps, halos, frizz, semi-transparent edges, or inner line hatching.',
    '- Do not change cut, part side, length, or ear visibility.',
    '- Motion does not create flyaways; silhouette/part/length remain unchanged.',
    '- HAIR COLOR: EXACTLY match BASE hair color (no hue/sat/brightness changes; ignore any color in HAIR CHIP).',
    '- HAIR IS REQUIRED — do NOT omit hair.'
  ];
  const map = {
    'side-part': [
      `- PART on character's RIGHT (viewer's LEFT); sweep LEFT.`,
      `- Both ears fully visible; no hair below ear top.`,
      `- Back follows skull curve; no straight "bob" hem.`
    ],
    'ponytail': [`- One ponytail back; no loose face strands.`],
    'pigtails': [`- Two mid-height tails; solid masses; face/ears clear.`],
