}

function clothingLock(clothingType){
  const type = norm(clothingType);
  if (type === 'dress') {
    return [
      'OUTFIT / CLOTHING LOCK:',
      `- Outfit MUST remain a DRESS as in ${LABEL_BASE} (single-piece).`,
      '- Do NOT replace with a T-shirt and shorts, pants, or layered outfits.',
      `- Keep the same dress silhouette as ${LABEL_BASE}; no waist seam or shorts hem visible.`
    ].join('\n');
  }
  return [
    'OUTFIT / CLOTHING LOCK:',
    `- Outfit MUST remain a short-sleeve T-SHIRT and SHORTS as in ${LABEL_BASE}.`,
    '- Do NOT replace with a dress, skirt, pants, or layered outfits.',
    `- Keep shorts length and T-shirt silhouette consistent with ${LABEL_BASE}.`
  ].join('\n');
}

function buildPoseLock(n){
  const core = POSE_PROMPT_MAP[String(n)] || '';
  const negs = POSE_NEGATIVES[String(n)] || [];
  const lines = [
    `POSE LOCK — ID ${n}`,
    core,
    `FOLLOW ${LABEL_POSE} EXACTLY for limb positions, weight/ground contact, and hand orientation.`,
    `If any instruction conflicts, this POSE LOCK (with ${LABEL_POSE}) outranks all other guidance.`
  ];
  if (negs.length) {
    lines.push('NEGATIVES (what NOT to do):');
    negs.forEach(x => lines.push(`  - ${x}`));
  }
  return lines.join('\n');
}

function buildFraming(poseNum){
  return [
