/* ========== FINAL PROMPT BLOCK ========== */
const posePromptBlock = (posePromptPreface ? `${posePromptPreface}\n\n` : '') + baseBlock;

/* ========== OUTPUT JSON ========== */
const crypto = require('crypto');
