}

// 2) Derive a sane key if upstream didn’t provide one
// You can override any of these via input JSON:
//   assetsRoot          -> defaults to 'book-mvp-simple-adventure'
//   orderAssetsPrefix   -> defaults to 'order-generated-assets'
//   characterPath       -> defaults to `characters/<characterHash>`
//   baseCharacterFilename -> defaults to 'base-character.png'

const assetsRoot = j.assetsRoot || j.bookSlug || 'book-mvp-simple-adventure';
const orderPrefix = j.orderAssetsPrefix || 'order-generated-assets';

const hash = j.characterHash || j.__meta?.characterHash;
const charDir = j.characterPath || (hash ? `characters/${hash}` : null);
if (!charDir) throw new Error('Resolve Base Character Key: characterPath or characterHash required.');

const filename = j.baseCharacterFilename || 'base-character.png';

// Build key
const key = `${assetsRoot}/${orderPrefix}/${charDir}/${filename}`;

// Also build public URL if you have a CDN/public R2 base
const baseUrl = j.publicR2Url ? String(j.publicR2Url).replace(/\/$/, "") : undefined;
const url = baseUrl ? `${baseUrl}/${key}` : undefined;

return [{ json: { ...j, baseCharacterKey: key, baseCharacterUrl: url }, binary: $binary }];

// 🧪 MOCK: Gemini Image Generation (EACH mode)
