// Upload Pose Artifact — EACH — v2.4 (fixed + robust IDs)
// Accepts $binary.generated (new extractor) and legacy keys; uploads pose to R2 with retry-versioned filename

const j = $json || {};
const b = $binary || {};

/* ---------------- helpers ---------------- */
function zpad(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : null; }
function clampPose(n){ return Math.max(0, Math.min(999, Number(n || 0))); }
function isHex(s){ return typeof s === 'string' && /^[a-f0-9]{8,64}$/i.test(s); }

function derivePoseNN(j){
  // Prefer explicit fields from upstream
  if (typeof j.poseNN === 'string' && j.poseNN) return j.poseNN;
  if (typeof j.poseNN_hyphen === 'string' && j.poseNN_hyphen) return j.poseNN_hyphen;
  if (typeof j.poseLabel === 'string' && j.poseLabel) return j.poseLabel;

  // Derive from poseNumber/currentPoseNumber/__meta.poseNumber
  const raw = j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber;
  const n = Number.isFinite(Number(raw)) ? clampPose(raw) : null;
  return n ? `pose-${zpad(n)}` : null;   // standardize on hyphen form (pose-01)
}

function deriveCharacterHash(j){
  // Prefer explicit, but only if it looks like a real hex hash
  if (isHex(j.characterHash)) return String(j.characterHash);

  // Common string haystacks to mine
  const haystacks = [
    j.baseCharacterKey, j.baseRefPublicUrl, j.uploadKey, j.generatedFileName,
    j.correlationId, j.baseCharacterUrl, j.basePublicUrl
  ].filter(Boolean).map(String);

  // /characters/<hex>/...
  for (const s of haystacks){
    let m = s.match(/\/characters[\/_\-]([a-f0-9]{8,64})[\/_\-]/i);
    if (m && isHex(m[1])) return m[1];

    // ...characters_<hex>_pose...
    m = s.match(/characters[\/_\-]?([a-f0-9]{8,64})[\/_\-]pose/i);
    if (m && isHex(m[1])) return m[1];

    // correlationId like "<hex>-POSE01..."
    m = s.match(/([a-f0-9]{8,64})-POSE/i);
    if (m && isHex(m[1])) return m[1];
  }

  return null;
}

/* ---------------- identity ---------------- */
const assetsRoot = j.assetsRoot || 'book-mvp-simple-adventure/order-generated-assets';
const poseNN     = derivePoseNN(j);
const characterHash = deriveCharacterHash(j);

if (!characterHash || !poseNN) {
  const dbg = {
    haveCharacterHash: !!characterHash,
    havePoseNN: !!poseNN,
    poseNumber: j.poseNumber,
    currentPoseNumber: j.currentPoseNumber,
    metaPoseNumber: j.__meta?.poseNumber,
    correlationId: j.correlationId,
    baseCharacterKey: j.baseCharacterKey,
    baseRefPublicUrl: j.baseRefPublicUrl,
    generatedFileName: j.generatedFileName,
    presentBinaryKeys: Object.keys(b||{})
  };
  throw new Error(`UPLOAD_MISSING_IDENTITY: characterHash and poseNN required — debug=${JSON.stringify(dbg)}`);
}

/* ---------------- filename + path ---------------- */
const retryAttempt = Number.isFinite(Number(j.retryAttempt)) ? Number(j.retryAttempt) : 0;
const retrySuffix  = retryAttempt > 0 ? `_r${retryAttempt}` : '';
const filename     = `${poseNN}${retrySuffix}.png`;
const uploadKey    = `${assetsRoot}/characters/${characterHash}/poses/${filename}`.replace(/\/\//g, '/');

/* ---------------- select binary ---------------- */
let imageData = null;
let binaryKey = null;
for (const k of ['generated', 'generatedImage', 'data', 'image']) {
  if (b[k]) { imageData = b[k]; binaryKey = k; break; }
}
if (!imageData) {
  throw new Error('UPLOAD_MISSING_BINARY: No image binary found (expected $binary.generated from Extract Generated Image)');
}

/* ---------------- normalize binary ---------------- */
const outBinary = {
